import{_ as n,C as s,o as t,c as o,a3 as a,b as l,w as i,a as d,E as c,a4 as h}from"./chunks/framework.DhF4LrUq.js";const y=JSON.parse('{"title":"Artifact pipeline","description":"The artifact pipeline - upload with provenance, the seven-stage validation FSM, and immutable SHA-256-identified binaries.","frontmatter":{"description":"The artifact pipeline - upload with provenance, the seven-stage validation FSM, and immutable SHA-256-identified binaries."},"headers":[],"relativePath":"concepts/artifact-pipeline.md","filePath":"concepts/artifact-pipeline.md"}'),p={name:"concepts/artifact-pipeline.md"};function u(g,e,f,m,b,A){const r=s("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="artifact-pipeline" tabindex="-1">Artifact pipeline <a class="header-anchor" href="#artifact-pipeline" aria-label="Permalink to &quot;Artifact pipeline&quot;">​</a></h1><p>An artifact is a concrete, immutable binary — an IPA, APK, or AAB. Everything the platform promises (reproducible releases, trustworthy manifests, evidence) rests on artifacts being exactly what they claim to be, so the pipeline between upload and usability is explicit and mechanical.</p><h2 id="upload" tabindex="-1">Upload <a class="header-anchor" href="#upload" aria-label="Permalink to &quot;Upload&quot;">​</a></h2><p>Developers upload through the Console, the <code>shipperdog</code> CLI, or CI. Two paths, one outcome:</p><ul><li><strong>Direct upload</strong> for binaries at or under the resumable threshold (100 MB).</li><li><strong>Direct-to-storage sessions</strong> for larger binaries: the platform grants a session URL, the client streams bytes straight to object storage, and a finalize call registers the artifact.</li></ul><p>Alongside the bytes, uploads can carry <strong>build provenance</strong> — git commit, git branch, pipeline name, CI run URL, build timestamp. The CI integrations attach these automatically from the pipeline context. They are claims validated for shape, recorded once, and never fabricated: a manual upload may assert none.</p><p>Two rules hold from the first byte:</p><ul><li><strong>Immutability.</strong> Stored artifacts are write-once. Re-uploading identical content registers a new artifact (with a pointer to the duplicate); nothing is ever overwritten or deleted.</li><li><strong>The version freeze.</strong> The moment a version carries any release — a draft counts — its artifact set is frozen. Corrections are a new version, never an edit.</li></ul><h2 id="extraction" tabindex="-1">Extraction <a class="header-anchor" href="#extraction" aria-label="Permalink to &quot;Extraction&quot;">​</a></h2><p>Parsing is asynchronous, after the upload returns: the binary&#39;s identity fields — bundle id, version name, minimum OS, build number — are extracted from the binary itself, not from what the uploader claims. iOS provisioning-profile facts and Android signing-block presence are recorded as metadata. The upload response is always &quot;pending&quot;; read the artifact back to see extraction settle.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Once extraction settles, a second async pipeline runs seven ordered stages, recording every outcome on the artifact:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE -&gt; FORMAT -&gt; METADATA -&gt; CHECKSUM -&gt; SIGNING -&gt; APPLICATION_MATCH -&gt; VERSION_MATCH -&gt; READY</span></span></code></pre></div><ol><li><strong>FILE</strong> — the stored object exists and matches the registered size.</li><li><strong>FORMAT</strong> — the container verdict is structural (detected from the bytes, never the file name), and coherent with the platform and extension. A renamed binary fails with the structural truth recorded.</li><li><strong>METADATA</strong> — extraction succeeded; a malformed binary fails here with its actionable code.</li><li><strong>CHECKSUM</strong> — the stored bytes re-prove the registered SHA-256.</li><li><strong>SIGNING</strong> — presence and self-consistency: an iOS build must carry a coherent, unexpired provisioning profile; an APK must carry a v2 or v3 signing block.</li><li><strong>APPLICATION_MATCH</strong> — the extracted bundle id / package name equals the registered application identifier.</li><li><strong>VERSION_MATCH</strong> — the extracted marketing version (and, when pinned, the CI build number) equals the version record.</li></ol><p>The first failed stage stops the run; later stages record &quot;skipped&quot;. A failed artifact&#39;s read answers exactly which stage, which code, and what to do.</p><h2 id="the-state-machine" tabindex="-1">The state machine <a class="header-anchor" href="#the-state-machine" aria-label="Permalink to &quot;The state machine&quot;">​</a></h2>',16)),(t(),l(h,null,{default:i(()=>[c(r,{id:"mermaid-98",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20UPLOADING%20--%3E%20VALIDATING%20%3A%20registered%2C%20bytes%20stored%2C%20checksum%20known%0A%20%20%20%20VALIDATING%20--%3E%20READY%20%3A%20seven-stage%20pipeline%20passed%0A%20%20%20%20VALIDATING%20--%3E%20FAILED%20%3A%20a%20stage%20failed%0A%20%20%20%20FAILED%20--%3E%20VALIDATING%20%3A%20revalidate%20(the%20retry%20entry)%0A%20%20%20%20READY%20--%3E%20DISTRIBUTED%20%3A%20serving%20a%20release%20audience%0A%20%20%20%20READY%20--%3E%20ARCHIVED%20%3A%20archived%0A%20%20%20%20DISTRIBUTED%20--%3E%20ARCHIVED%20%3A%20archived%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<ul><li><code>READY</code> is the state releases and version grants accept — nothing distributes off a failed or still-validating binary.</li><li><strong>Revalidation is the retry path</strong>: a failed artifact re-enters through <code>FAILED -&gt; VALIDATING</code> and the pipeline re-runs. Deterministic failures reproduce their verdict, but the world may have changed (a corrected registry identifier, recovered storage) — the retry is how the corrected fact wins.</li><li>There is deliberately <strong>no revoked artifact state</strong> — revocation is an authorization lifecycle (a version&#39;s distribution can be revoked), never a mutation of the binary&#39;s record.</li><li>Infrastructure hiccups (queue full, storage briefly unreadable) are recorded blocks, not failures: the artifact stays <code>VALIDATING</code> and the stall is visible rather than silent.</li></ul><h2 id="where-the-artifacts-live" tabindex="-1">Where the artifacts live <a class="header-anchor" href="#where-the-artifacts-live" aria-label="Permalink to &quot;Where the artifacts live&quot;">​</a></h2><p>Binaries live in object storage under a path keyed by organization, tenant, application, version, and artifact id; PostgreSQL holds only metadata, never bytes. Downloads never hand out that layout — testers receive short-lived signed URLs minted per decision (see the <a href="/shipperdog/snapshot/concepts/security-model">security model</a>).</p><h2 id="where-to-go-deeper" tabindex="-1">Where to go deeper <a class="header-anchor" href="#where-to-go-deeper" aria-label="Permalink to &quot;Where to go deeper&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/concepts/release-lifecycle">Release lifecycle</a> — what happens once artifacts are READY</li><li>Developer detail: the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/artifacts.md" target="_blank" rel="noreferrer">artifacts</a> module doc (routes, extraction failure codes, the validation stages, provenance field contract).</li></ul>',5))])}const T=n(p,[["render",u]]);export{y as __pageData,T as default};
